 "content": "def transform(grid):
    # Extend each nonzero marker upward: the horizontal run of 1s immediately
    # to its right determines the tower height, clipped by available rows.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value not in (2, 8):
                continue
            run = 0
            j = c + 1
            while j < w and row[j] == 1:
                run += 1
                j += 1
            height = min(run + 1, r)
            for k in range(1, height + 1):
                out[r-k][c] = value if k == height else 1
    return out
